class ProfileScope
{
public:
    ProfileScope(
        Profiler& profiler,
        StringID name)
        : m_Profiler(&profiler),
          m_Name(name),
          m_Start(
              Clock::now())
    {}

    ~ProfileScope() noexcept
    {
        m_Profiler->Record(
            m_Name,
            Clock::now() -
                m_Start);
    }

private:
    Profiler* m_Profiler;
    StringID m_Name;
    TimePoint m_Start;
};

